char stack_mem[8192];
void *stack_top = stack_mem + sizeof(stack_mem);

struct clone_args args = {
    .flags = CLONE_NEWNET | CLONE_NEWPID | CLONE_VM,
    .exit_signal = SIGCHLD,
    .stack = (uint64_t)stack_top,
    .stack_size = sizeof(stack_mem),
    // Additional settings for tid pointers omitted for brevity
};

// Returns 0 in child, PID of child in parent, -1 on error
long new_pid = syscall(SYS_clone3, &args, sizeof(args));

if (new_pid == 0) {
    // Child execution context starts here
}
